{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin doğrulanması için sisteme girdi verilerek harita üzerindeki görsel çıktı ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi yapılarak 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı ölçülmelidir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün bir izi seçmesiyle ekranda doğru bilgilerin (kimlik, hız, yön, zaman) görüntülenip görüntülenmediği gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla 30 ve 120 saniye sonrası iz durumundaki değişimlerin (işaretlenme ve kaldırılma) gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği sistemin çalıştırılmasıyla doğrulanmalıdır."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderimi sonrası iletim süresinin 2 saniyeyi aşmaması ve durum bildiriminin gösterilmesi gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Kayıtların oluşturulması testle doğrulanırken, logların değiştirilemezlik özelliği ve formatı kod veya yapılandırma incelemesiyle kontrol edilmelidir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun durdurulmasıyla yedek sunucunun devralma süresi ve veri bütünlüğünün korunması senaryo testiyle gözlemlenmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, belirli bir istek hızında sisteme girdi verilerek gözlemlenmesiyle doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında (2.000 istek/sn) 99. persentil gecikme metriklerinin karşılaştırılması, performans testlerinin sonuçlarının istatistiksel analizi gerektirdiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç servisin yanıt vermemesi durumunda zaman aşımının tetiklenmesi ve HTTP 504 yanıtının, simüle edilmiş gecikme senaryolarında sistemin çalıştırılarak gözlemlenmesiyle doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve devam eden istekleri düşürmeden uygulanması, canlı sistem üzerinde değişiklik yapılarak ve istek akışı izlenerek test edilmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin loglanma davranışı, sisteme istek gönderilip ardından üretilen günlük dosyalarının içeriğinin gözlemlenmesiyle doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun süreli izleme verilerinin veya sistem mimarisinin istatistiksel analizi gerektirdiği için analiz yöntemi seçilmiştir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı senaryosu üzerinden sistemin çalıştırılması ve girdi verilerek gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı senaryoları ile sistemin çalıştırılarak gözlemlenmesi gerekmektedir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık kilit süresinin, sisteme girdi verilerek ve sonuçların gözlemlenerek test edilmesi en uygun yöntemdir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının sistemin çalıştırılarak farklı girdilerle denetlenmesi ve kabul/red davranışlarının gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildiriminin gerçekleşip gerçekleşmediği, başvuru sürecinin çalıştırılması ve çıktıların gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme işlevi ve 30 günlük süre içinde kaldığı yerden devam etme özelliğinin, sistemin çalıştırılarak ve zamanlama senaryoları ile gözlemlenerek test edilmesi gerekmektedir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzü kodunun, yapılandırmasının ve erişilebilirlik araçlarının çıktılarının gözle denetlenerek (inceleme) doğrulanması standart bir uygulamadır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanıp saklanmadığının, altyapı yapılandırma belgelerinin ve sunucu konumlarının gözle denetlenerek (inceleme) doğrulanması gerekir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-AI-004-01",
      "title": "95th percentile response time under 50 rps load",
      "covers": [
        "AI-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The Document Classification Service is deployed and operational. A load testing tool capable of generating sustained load and recording response times is available. A dataset of valid document files suitable for classification is prepared.",
      "test_inputs": "A set of valid document files (e.g., 1000 unique PDFs or text files) to be used for requests.",
      "assumptions": "The test environment is isolated from production traffic. The load generator can sustain exactly 50 requests per second. The definition of 'request' is a single HTTP POST/GET call to the classification endpoint with a valid document payload. Response time is measured from request initiation to the first byte of the response or full response receipt (standard definition for such SLAs).",
      "steps": [
        {
          "no": 1,
          "action": "Initiate a load test that sends classification requests to the service at a constant rate of 50 requests per second for a duration sufficient to collect a statistically significant sample of response times (e.g., 5 minutes, resulting in 15,000 requests).",
          "expected": "The load test completes successfully without the service crashing or becoming unresponsive. A log of response times for all successful requests is generated."
        },
        {
          "no": 2,
          "action": "Calculate the 95th percentile of the recorded response times from the load test results.",
          "expected": "The calculated 95th percentile response time is less than or equal to 500 ms."
        }
      ]
    }
  ]
}

