{
  "test_cases": [
    {
      "id": "TC-MED-008-01",
      "title": "Battery endurance verification under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet battery is fully charged (100%). The 'defined usage profile' configuration is active on the device.",
      "test_inputs": "",
      "assumptions": "The 'defined usage profile' is a specific, documented sequence of operations (e.g., screen on, GPS active, Wi-Fi on, specific CPU load) agreed upon by the test team. The test duration is monitored via the system clock.",
      "steps": [
        {
          "no": 1,
          "action": "Start the application and initiate the defined usage profile on the fully charged tablet.",
          "expected": "The application runs normally, and the battery level indicator is at 100%."
        },
        {
          "no": 2,
          "action": "Allow the tablet to operate continuously under the defined usage profile for 8 hours without interruption.",
          "expected": "The tablet remains operational, and the application is responsive throughout the 8-hour period."
        },
        {
          "no": 3,
          "action": "Check the battery status after 8 hours of operation.",
          "expected": "The battery level is greater than 0%, and the tablet has not powered off."
        }
      ]
    },
    {
      "id": "TC-MED-008-02",
      "title": "Battery endurance verification at boundary limit",
      "covers": [
        "MED-008"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The tablet battery is fully charged (100%). The 'defined usage profile' configuration is active.",
      "test_inputs": "",
      "assumptions": "The 'defined usage profile' represents the maximum expected sustained load for the application.",
      "steps": [
        {
          "no": 1,
          "action": "Start the defined usage profile on the fully charged tablet.",
          "expected": "The application is running and consuming power as per the profile."
        },
        {
          "no": 2,
          "action": "Monitor the battery level continuously until it reaches a critical threshold (e.g., 10-15%) or the 8-hour mark, whichever comes first.",
          "expected": "If the battery reaches a critical threshold before 8 hours, the system should provide a low battery warning. If the 8-hour mark is reached before critical threshold, the device must still be functional."
        },
        {
          "no": 3,
          "action": "Verify the device state exactly at the 8-hour mark.",
          "expected": "The device is still powered on and the application is operational, confirming it meets the 'at least 8 hours' requirement."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Verification of top three contributing passages for a document",
      "covers": [
        "AI-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The Document Classification Service is running and accessible.",
      "test_inputs": "A text document containing at least four distinct sentences or paragraphs.",
      "assumptions": "The service returns a structured response (e.g., JSON) containing a list of passages and their contribution scores.",
      "steps": [
        {
          "no": 1,
          "action": "Submit the test document to the classification service.",
          "expected": "The service returns a successful classification response."
        },
        {
          "no": 2,
          "action": "Inspect the response for the list of contributing passages.",
          "expected": "The response contains exactly three text passages identified as the most contributing."
        },
        {
          "no": 3,
          "action": "Verify the content of the returned passages.",
          "expected": "Each of the three passages corresponds to a substring of the original input document."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Verification of contributing passages for a short document",
      "covers": [
        "AI-007"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The Document Classification Service is running and accessible.",
      "test_inputs": "A text document containing exactly three distinct sentences.",
      "assumptions": "The service treats each sentence as a distinct passage candidate.",
      "steps": [
        {
          "no": 1,
          "action": "Submit the short test document to the classification service.",
          "expected": "The service returns a successful classification response."
        },
        {
          "no": 2,
          "action": "Inspect the response for the list of contributing passages.",
          "expected": "The response contains exactly three text passages."
        },
        {
          "no": 3,
          "action": "Verify the content of the returned passages.",
          "expected": "The three returned passages match the three sentences in the input document."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Verification of contributing passages for a document with fewer than three distinct segments",
      "covers": [
        "AI-007"
      ],
      "type": "Hata",
      "priority": "Düşük",
      "preconditions": "The Document Classification Service is running and accessible.",
      "test_inputs": "A text document containing only one single sentence.",
      "assumptions": "The service defines a 'passage' as a sentence or paragraph; if fewer than three distinct passages exist, it may return fewer or handle it gracefully.",
      "steps": [
        {
          "no": 1,
          "action": "Submit the single-sentence test document to the classification service.",
          "expected": "The service processes the request without crashing."
        },
        {
          "no": 2,
          "action": "Inspect the response for the list of contributing passages.",
          "expected": "The service either returns the single available passage or returns an empty list/error message, but does not return duplicate entries to fake three passages."
